import { knownRunFailureReasonSchema } from "../contracts/run-failure-reasons";

/** Closed domain cases, separate from the extensible raw wire/cache token. */
export function renderSwiftRunFailureReasons(): string {
  const cases = knownRunFailureReasonSchema.options.map((reason) => {
    const name = reason.replaceAll(/_([a-z0-9])/gu, (_, letter: string) => {
      return letter.toUpperCase();
    });
    return `  case ${name} = "${reason}"`;
  });
  return [
    "// @generated by @okouai/api-contracts. Do not edit by hand.",
    "// Regenerate with: cd turbo && pnpm -F @okouai/api-contracts generate:swift",
    "",
    "/// Known at build time. Keep transport and cache values as raw strings.",
    "public enum KnownRunFailureReason: String, CaseIterable, Sendable {",
    ...cases,
    "}",
    "",
  ].join("\n");
}
